// suborned.life/1: the district's day as rules, written to contracts/world/<plan id>.life.json (generated by Pulse from the plan,
// the r008 timetable and the GDD). Rules, not individuals: Splice generates people and vehicles from it at build time, Keel steps them.
// Tags in `src`: [P] plan, [T] timetable, [G] GDD, [S] starting value to tune by playtest. Day clock in hours (0-24) unless marked.
export type BandId = 'night' | 'early' | 'morning' | 'afternoon' | 'peak' | 'evening' | 'late';
export type ByBand<T = number> = Record<BandId, T>;
export type Hours = [number, number] | 'service'; // [open, close], wraps past 24; 'service' = station hours

export type Life = {
  schema: 'suborned.life/1';
  plan: { id: string; version: string; file: string };
  clock: {
    unit: 's'; scale: string; day: { start: string; end: string };
    mission: { windowMin: [number, number]; note: string }; // 1 mission s = 1 day s; a mission sets its own start (contracts/missions/<id>/), the world holds none
    bands: { id: BandId; from: number; to: number }[];
  };
  transit: {
    serviceHours: { from: number; to: number }; headwayMultiplierByBand: ByBand; loadByBand: ByBand; walkSpeed: number;
    services: Service[]; // departure k = phase + k x headwaySec; stop reached at departure + offsetSec[stop]
    interchange: { pairs: Record<string, string>; maxWalkM: number };
  };
  traffic: {
    laneWidth: number; byBand: ByBand;
    byClass: Record<'primary' | 'district' | 'access' | 'mall' | 'quay', { lanes: number; flowPerDirPeak: number; speed?: number; mix: Record<string, number>; note: string }>;
    areaBias: Record<string, Record<string, number>>;
  };
  deliveries: {
    visitsPerUnitPerDay: Record<string, number>; bandShare: ByBand; vehicle: { default: string; trade: string; dwellSec: Record<string, number>; blocksLane: string[] };
    expected: Record<string, { visitsPerDay: number; perHour: ByBand }>;
  };
  pedestrians: {
    walkSpeed: number; pavement: number; spillDepth: number; lastLegM: number; reachM: number; feederShare: number; walkersMultiplier: number;
    densityTarget: { value: number; unit: string; where: string; src: string };
    category: Record<string, { floorRho: number; spillRho: number; dwell: number; draw: ByBand; trades: string[] }>;
    promenade: Record<'mall' | 'walk' | 'square' | 'road', ByBand>; // people/m2 of public ground
    levels: { street: { z: number }; deck: { z: number; promenade: ByBand; tripShare: number }; concourse: { z: number; promenade: ByBand } };
  };
  residents: { tripsPerHour: ByBand; grossPerHomeM2: number; perHome: number; efficiency: number; builtShare: number; rule: string };
  events: { list: { id: string; area: string; windowS: number; surge: number; who: string; src: string; atHours: number[] }[] }; // the world's own recurring events; mission events live with the mission
  character: { thresholds: { lively: number; steady: number }; table: Record<string, ByBand<{ score: number; mood: 'lively' | 'steady' | 'quiet' }>>; standing: string };
  generator: {
    occupations: Record<string, { category: string; hours: Hours; meanWidth: number; depth: number; staffPerUnit: number; shifts: { lengthH: number } | string }>;
    expected: { workersPerArea: Record<string, { frontageMetres: number; units: number; staff: number; trades: Record<string, { units: number }> }> };
    homes: { plot: string; area: string; use: string; residents: number }[];
    commuters: { rule: string; stations: string[] };
    routines: Record<'worker' | 'resident' | 'shopper' | 'reveller' | 'docker', string[]>;
    tiers: { simulated: string; background: string; maxCombatants: number; src: string };
  };
};
export type Service = {
  line: string; headwaySec: number; dwellSec: number; speed: number; stops: string[]; runSec: number[];
  offsetSec: Record<string, number>; loadPerService: Record<string, number>;
};
